112	                    Color::Black => "B",
113	                    Color::Red => "R",
114	                    Color::Green => "G",
115	                })?,
116	                ManaSymbol::Colorless(n) => {
117	                    for _ in 0..*n {
118	                        write!(f, "{{C}}")?;
119	                    }
120	                }
121	                ManaSymbol::X => write!(f, "{{X}}")?,
122	            }
123	        }
124	        Ok(())
125	    }
126	}
